#include <algorithm>
#include <iostream>
#include <vector>

// generated by Gemini

int main() {
    std::vector<int> nums = {10, 25, 4, 30, 15};
    int threshold = 20;
    int removed_count = 0;

    // [=] captures threshold by copy; [&] captures removed_count by reference
    auto new_end = std::remove_if(nums.begin(), nums.end(), [=, &removed_count](int x) {
        if (x > threshold) {
            ++removed_count; // Modifies local removed_count outside the lambda
            return true;
        }
        return false;
    });

    nums.erase(new_end, nums.end());

    std::cout << "Removed: " << removed_count << '\n'; // Removed: 2
    for (int n : nums) {
        std::cout << n << ' '; // 10 4 15
    }
}
